 const R=JSON.parse(document.getElementById('emerging-reference-data').textContent),END='2026-06-30',months=Array.from({length:12},(_,i)=>`${i<6?2025:2026}-${String(i<6?i+7:i-5).padStart(2,'0')}`);
 const states={newRepo:{query:'',domain:'',platform:'',age:'',sort:'openrank',page:0,size:10,selected:['1','2','6']},newProject:{query:'',domain:'',platform:'',age:'',sort:'openrank',page:0,size:10,selected:['1','2','5']}};
