 function tools(b,keep=false){const d=scope(b),st=states[d];b.el.querySelector('.cr-head h4').textContent=d==='newRepo'?'全球新势力仓库影响力 Top 30':'全球新势力项目影响力 Top 30';b.el.querySelector('.cr-head-right>span').textContent='';if(!keep)b.toolbar.innerHTML=`<span class="er-scope-tag">${d==='newRepo'?'单个代码仓库':'项目 · 多仓库聚合'}</span>`+field('size','每页',[10,20,30],st.size)+`<label class="cr-search">检索<input type="search" data-er-search value="${E(st.query)}" placeholder="${d==='newRepo'?'完整仓库路径 / 项目 / 领域':'项目 / 组织 / 领域'}" aria-label="检索完整${d==='newRepo'?'仓库':'项目'}榜单"></label>`+ebtn('重置','reset');}
